// Parity: the Taller de bajo engine (casos.json, generated by casos.mjs from the built page)
// against the REAL MidiGenPlay C# — ChordArticulator.PlanHits, AccentDeriver.MarkFills and
// BassAccentFollow.PlanEvent, wired exactly as BassTrackComposer.ExpandForAccents wires them.
// Run: dotnet run -c Release -p:MgpDll=<path to MidiGenPlay.Runtime.dll>
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using MidiGenPlay;
using MidiGenPlay.Composition;
using static MidiGenPlay.Composition.BasslineCardConfigSO;

static class Paridad
{
    static int Main(string[] args)
    {
        var path = args.Length > 0 ? args[0] : Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "casos.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        int n = 0, bad = 0, notes = 0, attacks = 0, flags = 0;
        foreach (var c in doc.RootElement.EnumerateArray())
        {
            n++;
            string id = c.GetProperty("id").GetString();
            int bpb = c.GetProperty("bpb").GetInt32();

            // --- MarkFills ---
            var acc = c.GetProperty("accentsRaw").EnumerateArray().Select(a => new MidiGenerator.AccentPoint
            { beat = a.GetProperty("b").GetDouble(), weight = (float)a.GetProperty("w").GetDouble() }).ToList();
            var fills = c.GetProperty("fills").EnumerateArray().Select(f => new DrumFillPlanner.FillChoice
            { measure = f.GetProperty("m").GetInt32(), startBeat = f.GetProperty("start").GetInt32() }).ToList();
            AccentDeriver.MarkFills(acc, fills, bpb);
            var expFill = c.GetProperty("expectFill").EnumerateArray().Select(x => x.GetBoolean()).ToList();
            for (int i = 0; i < acc.Count; i++)
            {
                flags++;
                if (acc[i].isFill != expFill[i]) { Fail(ref bad, id, $"isFill at beat {acc[i].beat}: C# {acc[i].isFill}, JS {expFill[i]}"); break; }
            }

            // --- bass render ---
            var st = c.GetProperty("settings");
            var s = new BassAccentFollow.Settings
            {
                mode = st.GetProperty("mode").GetString() == "attacks" ? AccentFollowMode.Attacks : AccentFollowMode.Reinforce,
                threshold = (float)st.GetProperty("threshold").GetDouble(),
                maxAttacksPerBar = st.GetProperty("cap").GetInt32(),
                boost = st.GetProperty("boost").GetInt32(),
                offCut = st.GetProperty("cut").GetInt32(),
                fillMode = st.GetProperty("fill").GetString() == "follow" ? AccentFillMode.Follow : AccentFillMode.Gap,
            };
            var budget = new Dictionary<int, int>();
            var got = new List<BassAccentFollow.Atom>();
            foreach (var e in c.GetProperty("events").EnumerateArray())
            {
                var expr = Enum.Parse<ChordExpressionType>(e.GetProperty("expr").GetString());
                var rate = Enum.Parse<ArpeggioRate>(e.GetProperty("rate").GetString());
                var hits = ChordArticulator.PlanHits(expr, rate, e.GetProperty("start").GetDouble(),
                    e.GetProperty("len").GetDouble(), bpb, 1, e.GetProperty("vel").GetInt32());
                var atoms = hits.Select(h => new BassAccentFollow.Atom
                { start = h.StartBeats, dur = h.DurBeats, velocity = h.Velocity, canAttack = true })
                    .OrderBy(a => a.start).ToList();
                got.AddRange(BassAccentFollow.PlanEvent(atoms, acc, s, bpb, budget));
            }

            var exp = c.GetProperty("expect").EnumerateArray().ToList();
            notes += got.Count; attacks += got.Count(a => a.isAttack);
            if (exp.Count != got.Count) { Fail(ref bad, id, $"note count: C# {got.Count}, JS {exp.Count}"); continue; }
            for (int i = 0; i < got.Count; i++)
            {
                var x = exp[i]; var g = got[i];
                if (Math.Abs(g.start - x.GetProperty("s").GetDouble()) > 1e-9 ||
                    Math.Abs(g.dur - x.GetProperty("d").GetDouble()) > 1e-9 ||
                    g.velocity != x.GetProperty("v").GetInt32() ||
                    g.isAttack != x.GetProperty("atk").GetBoolean() ||
                    g.onAccent != x.GetProperty("on").GetBoolean())
                {
                    Fail(ref bad, id, $"note {i}: C# ({g.start},{g.dur},{g.velocity},{g.isAttack},{g.onAccent}) " +
                                      $"JS ({x.GetProperty("s")},{x.GetProperty("d")},{x.GetProperty("v")},{x.GetProperty("atk")},{x.GetProperty("on")})");
                    break;
                }
            }
        }
        Console.WriteLine($"{n} cases, {notes} bass notes ({attacks} new attacks), {flags} fill flags: " +
                          (bad == 0 ? "ALL EQUAL" : $"{bad} DIFFERENT"));
        return bad == 0 ? 0 : 1;
    }

    static void Fail(ref int bad, string id, string what)
    {
        if (bad < 15) Console.WriteLine($"DIFF [{id}] {what}");
        bad++;
    }
}
